function summarize(text, ratio){
  text=String(text||'').trim();
  if(!text) return {error:'请输入文本'};
  ratio=(+ratio); if(isNaN(ratio)||ratio<=0)ratio=0.3; if(ratio>1)ratio=1;
  var sents=text.split(/[。．！？!?.；;\n]+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  if(sents.length<=1) return {summary:text, count:sents.length, ratio:ratio};
  var freq={};
  text.replace(/[a-zA-Z]+/g,function(w){w=w.toLowerCase();freq[w]=(freq[w]||0)+1;return w;});
  for(var i=0;i<text.length;i++){var ch=text[i]; if(/[一-鿿]/.test(ch)){freq[ch]=(freq[ch]||0)+1;}}
  function score(s){var sc=0; s.replace(/[a-zA-Z]+/g,function(w){sc+=(freq[w.toLowerCase()]||0);return w;}); for(var i=0;i<s.length;i++){var ch=s[i]; if(/[一-鿿]/.test(ch))sc+=(freq[ch]||0);} return sc;}
  var ranked=sents.map(function(s,i){return {s:s,sc:score(s),i:i};});
  ranked.sort(function(a,b){return b.sc-a.sc;});
  var k=Math.max(1,Math.round(sents.length*ratio));
  var top=ranked.slice(0,k).sort(function(a,b){return a.i-b.i;});
  return {summary:top.map(function(t){return t.s;}).join(' '), count:k, ratio:ratio, total:sents.length};
}
var EXPORTS={summarize:summarize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SummaryForgePure = EXPORTS; }
